  unfold produce
  conv_rhs => unfold host_transcript.Transcript.queries
  simp only [erase_bind,erase_observe,erase_lift,erase_coe,erase_pure,Aeneas.Std.bind_tc_ok,PV_L1_Projection.prod_case,PV_L1_QueryAbsorb.complete_result]
  repeat' first
    | with_reducible rfl
    | split <;> simp only [erase_bind,erase_observe,erase_lift,erase_coe,erase_pure,Aeneas.Std.bind_tc_ok,PV_L1_Projection.prod_case,PV_L1_QueryAbsorb.complete_result]
    | apply (Aeneas.Std.bind_eq_iff _ _ _).mpr
      intro value called
