  unfold produce readOrder
  apply PV_L1_FixedBind.bind_fixed _ _ [.call .queryScan 0] ((List.range 16).map (fun n => .call .queryScan (n+1)))
  · exact PV_L1_QueryAbsorb.completed_order _ _ _ _
  · intro firstState
    simp only [PV_L1_Projection.prod_case]
    repeat' first
      | apply bind_lift
        intro value
      | apply bind_observe
        intro value
      | exact fixed_lift _
      | exact fixed_pure _
      | split <;> simp only [PV_L1_Projection.prod_case]
    all_goals
      cases value <;> simp only [List.map_nil,PV_L1_Projection.prod_case]
      all_goals
        apply bind_lift
        intro outcome
        exact fixed_pure _
#print axioms completed_order
